// Generated by Trae Work
(function () {
  var style = getComputedStyle(document.documentElement);
  var accent = style.getPropertyValue('--accent').trim();
  var accent2 = style.getPropertyValue('--accent2').trim();
  var ink = style.getPropertyValue('--ink').trim();
  var muted = style.getPropertyValue('--muted').trim();
  var rule = style.getPropertyValue('--rule').trim();

  // 图 2：代表性行为单位减排因子对比（横向条形，按因子值升序 → 大值在顶部）
  var el = document.getElementById('chart-factor');
  if (!el || typeof echarts === 'undefined') return;
  var chart = echarts.init(el, null, { renderer: 'svg' });

  // 因子来源：MockStore.factors() 27 项中挑代表项
  var items = [
    { name: '自带购物袋 (0.05/次)', v: 0.05, cat: 'food' },
    { name: '拒一次性餐具 (0.08/次)', v: 0.08, cat: 'food' },
    { name: '自带水杯 (0.1/次)', v: 0.1, cat: 'food' },
    { name: '公交出行 (0.10/公里)', v: 0.10, cat: 'travel' },
    { name: '地铁出行 (0.12/公里)', v: 0.12, cat: 'travel' },
    { name: '步行 / 骑行 (0.19/公里)', v: 0.19, cat: 'travel' },
    { name: '光盘行动 (0.8/餐)', v: 0.8, cat: 'food' },
    { name: '节约用电 (0.785/度)', v: 0.785, cat: 'energy' },
    { name: '垃圾分类 (0.2/次)', v: 0.2, cat: 'food' },
    { name: '素食一餐 (1.5/次)', v: 1.5, cat: 'food' },
    { name: '废纸回收 (1.3/千克)', v: 1.3, cat: 'recycle' },
    { name: '塑料回收 (2.7/千克)', v: 2.7, cat: 'recycle' },
    { name: '节约燃气 (2.1/立方米)', v: 2.1, cat: 'energy' },
    { name: '旧物捐赠 (3.5/件)', v: 3.5, cat: 'recycle' },
    { name: '二手转卖 (4.0/件)', v: 4.0, cat: 'recycle' },
    { name: '旧衣回收 (6.0/千克)', v: 6.0, cat: 'recycle' },
    { name: '金属回收 (8.0/千克)', v: 8.0, cat: 'recycle' }
  ];
  // 按 v 升序 → ECharts y 轴类目从下到上
  items.sort(function (a, b) { return a.v - b.v; });

  var catColor = {
    travel: accent,
    energy: accent2,
    recycle: '#7C5CBF',
    food: '#3FB88F'
  };
  var legendUsed = [
    { key: 'travel', label: '绿色出行' },
    { key: 'energy', label: '节水节电' },
    { key: 'recycle', label: '旧物回收' },
    { key: 'food', label: '光盘行动' }
  ];

  chart.setOption({
    animation: false,
    tooltip: {
      trigger: 'item',
      appendToBody: true,
      formatter: function (p) {
        return p.name + '<br/>因子：' + p.value + ' kg CO₂e / 单位';
      }
    },
    legend: {
      top: 0,
      left: 'center',
      data: legendUsed.map(function (l) { return l.label; }),
      textStyle: { color: muted, fontSize: 12 },
      itemWidth: 14, itemHeight: 9
    },
    grid: { top: 34, left: 8, right: 56, bottom: 8, containLabel: true },
    xAxis: {
      type: 'value',
      name: 'kg CO₂e / 单位',
      nameTextStyle: { color: muted, fontSize: 11 },
      axisLabel: { color: muted, fontSize: 11 },
      splitLine: { lineStyle: { color: rule } }
    },
    yAxis: {
      type: 'category',
      data: items.map(function (d) { return d.name; }),
      axisLabel: { color: ink, fontSize: 11.5 },
      axisLine: { lineStyle: { color: rule } },
      axisTick: { show: false }
    },
    series: [{
      type: 'bar',
      barMaxWidth: 16,
      data: items.map(function (d) {
        return {
          value: d.v,
          itemStyle: { color: catColor[d.cat], borderRadius: [0, 4, 4, 0] }
        };
      }),
      label: {
        show: true,
        position: 'right',
        color: muted,
        fontSize: 11,
        formatter: function (p) { return p.value; }
      }
    }]
  });

  window.addEventListener('resize', function () { chart.resize(); });
})();
